export const SOURCE_URL = "https://github.com/theanshsonkar/emfirge";
export const INSTALL = "npx @emfirge/mcp install --privacy=strict";
export const MCP_CONFIG = `{
  "mcpServers": {
    "emfirge": {
      "command": "npx",
      "args": ["-y", "@emfirge/mcp"],
      "env": { "EMFIRGE_PRIVACY": "strict" }
    }
  }
}`;
export const CODEX_CONFIG = `[mcp_servers.emfirge]
command = "npx"
args = ["-y", "@emfirge/mcp"]

[mcp_servers.emfirge.env]
EMFIRGE_PRIVACY = "strict"`;
export const BRANCH_EXAMPLE = `// Tool calls made by your MCP client.
// Replace IDs with values from your own results.
emfirge_create_branch({
  base_analysis_id: "<analysis_id>",
  name: "reduce-db-exposure"
})

emfirge_apply_change({
  branch_id: "<branch_id>",
  op: "modify",
  resource_type: "rds_instance",
  resource_id: "<database_id>",
  fields: { publicly_accessible: false }
})

emfirge_branch_diff({ branch_id: "<branch_id>" })`;
export type DocSection = {
  id: string; title: string; paragraphs?: string[]; code?: string; language?: string;
  note?: string; bullets?: string[]; table?: { headers: string[]; rows: string[][] };
};
export type Doc = { slug: string; title: string; group: string; description: string; sections: DocSection[] };
const section = (id: string, title: string, paragraphs: string[], extra: Partial<DocSection> = {}): DocSection => ({ id, title, paragraphs, ...extra });
export const documents: Doc[] = [
  {
    slug: "quickstart", title: "Developer quickstart", group: "Get started",
    description: "Connect your agent, fork your cloud graph, and inspect a proposed change across its consequences before touching AWS.",
    sections: [
      section("before-you-start", "Before you start", ["You’ll need Node.js 20 or later, an MCP client, and an AWS account you are authorized to inspect. Emfirge’s MCP server runs locally over stdio and calls an Emfirge backend.", "These guides describe the checked-in MCP and engine. Make sure your server exposes the branch tools before following the branch workflow; the hosted deployment and installed package may differ."], {note:"A branch is a model of infrastructure. It does not create a second AWS environment or apply a real change."}),
      section("install", "1. Connect your agent", ["Run the installer in your terminal. It adds Emfirge to detected supported clients, including Claude Code, Claude Desktop, Cursor, Codex, and Kiro. Restart your client after installation.", "For a single client or manual setup, use [Connect agent](/connect)."], { code: INSTALL, language: "Terminal" }),
      section("map", "2. Create your cloud baseline", ["Ask your agent to call `emfirge_setup_help`. Hosted users receive their own ExternalId from `emfirge_setup`; self-host deployments must set `EMFIRGE_EXTERNAL_ID` on the server and in the MCP environment. There is no default, and scans refuse to run without it. Open the CloudFormation link, review the IAM template, and create the read-only role. The role includes two read-only CloudWatch permissions (`GetMetricStatistics` and `GetMetricData`) for in-use evidence, and two IAM Access Analyzer permissions (`CheckNoPublicAccess` and `ValidatePolicy`) used only by opt-in policy checks. Roles made with the old shared ExternalId must be redeployed. Once the stack is complete, copy `RoleArn` from Outputs.", "Give the agent the role ARN and the AWS region containing your resources. The region is required: an empty scan in the wrong region is not evidence that your account has no risks."], {code:`emfirge_scan({
  role_arn: "arn:aws:iam::123456789012:role/EmfirgeReadOnly",
  region: "us-east-1"
})`, language:"MCP tool call · example", note:"The account ID above is an example. Use your actual RoleArn and region, then save the analysis_id returned by the scan."}),
      section("branch", "3. Try a change on a branch", ["Create a named branch from the completed analysis, then add a change. Use a database ID that exists in that baseline. Changes accumulate on the branch in order."], {code:BRANCH_EXAMPLE, language:"MCP tool calls"}),
      section("review", "4. Review the consequences", ["Read added and removed relationships, findings, and internet reachability in the diff. Request a verdict to inspect native findings, optional scanner findings, and cost caveats together.", "Review coverage and uncertainty before taking a real action. Your own deployment workflow applies any approved change; Emfirge does not apply it."], {code:'emfirge_branch_verdict({ branch_id: "<branch_id>" })',language:"MCP tool call"}),
    ],
  },
  { slug:"concepts", title:"Key concepts", group:"Get started", description:"One shared model connects your cloud, a proposed change, and the consequences your agent needs to understand.", sections:[
    section("base", "Base snapshot", ["A completed analysis captures the collected infrastructure of an AWS account and region. This is the baseline for a branch. A snapshot reflects collection time; it is not a continuously synchronized view of production."]),
    section("branch", "Branch", ["A branch stores a base snapshot and an ordered list of changes. The engine rebuilds the hypothetical state by replaying those changes. Separate branches let you explore alternatives from the same baseline.", "A branch models resources and relationships. It is not a running environment, a Git checkout, or a production deployment."]),
    section("change", "Change", ["A change adds, modifies, or deletes a supported resource in the model. Its fields must match the resource schema. Changing a resource can affect relationships and findings elsewhere in the collected cloud."]),
    section("lens", "Lens", ["A lens evaluates one aspect of the model. Emfirge’s focused set covers Security and reachability, Configuration checks, Provisioned-cost estimates, Availability and recovery, and What needs a real run; each has its own coverage limits. See [Lenses and coverage](/docs/lenses)."]),
    section("diff", "Diff and verdict", ["The diff explains what changed compared with the base: resources, edges, findings, and reachability. The verdict summarizes selected consequences as `pass`, `warn`, or `block`.", "A pass means the current checks did not trigger a warning or block. It does not prove that a change is safe in a running application."]),
  ]},
  { slug:"branches", title:"Create and compare branches",group:"Work with branches",description:"Explore multiple changes against the same cloud baseline without changing the live account.",sections:[
    section("create", "Create a branch", ["Start with an `analysis_id` returned by a completed scan. Give the branch a name that describes the change you want to explore."], {code:'emfirge_create_branch({\n  base_analysis_id: "<analysis_id>",\n  name: "reduce-db-exposure"\n})',language:"MCP tool call"}),
    section("stack", "Stack changes", ["Each successful `emfirge_apply_change` appends a validated mutation. The engine rebuilds from the same base and applies the entire sequence in order. Only open branches can be changed.", "Use [Apply changes](/docs/changes) for supported resource types and examples."]),
    section("compare", "Compare alternatives", ["Create separate branches from the same base to compare designs. Pass their IDs to the comparison tool. The engine summarizes their modeled changes and outcomes across the documented lenses and ranks them according to its checks."],{code:'emfirge_list_branches({ base_analysis_id: "<analysis_id>" })\n\nemfirge_compare_branches({\n  branch_ids: ["<branch_a>", "<branch_b>"]\n})',language:"MCP tool calls",note:"A better modeled score is not a guarantee of application reliability or lower real-world spend."}),
    section("fork", "Fork a branch", ["Fork an open branch to try a variation without losing the original. The child copies the parent’s base snapshot and complete ordered change log, then evolves independently, like `git checkout -b`."],{code:'emfirge_fork_branch({\n  branch_id: "<branch_id>",\n  name: "reduce-db-exposure-v2"\n})',language:"MCP tool call"}),
    section("rollback", "Roll back changes", ["`emfirge_rollback_branch` removes the most recent change. Call it again to remove another; rolling back an empty change list is a no-op. To jump back several steps at once, `emfirge_rollback_branch_to_count` keeps only the first N changes, and 0 returns the branch to its base. The underlying AWS account is unaffected."],{code:'emfirge_rollback_branch({ branch_id: "<branch_id>" })\n\nemfirge_rollback_branch_to_count({\n  branch_id: "<branch_id>",\n  target_change_count: 2\n})',language:"MCP tool calls"}),
    section("revisions", "Work safely with several agents", ["`emfirge_get_branch` returns the branch’s ordered change log and a `branch_revision`, a SHA-256 of its history. Pass it to apply, rollback, rollback-to-count, or discard: if another agent changed the branch in the meantime, the call fails with HTTP 409 instead of silently building on a stale view."],{code:'emfirge_get_branch({ branch_id: "<branch_id>" })',language:"MCP tool call"}),
    section("discard", "Discard a branch", ["When an experiment is finished, discard it. The backend marks the branch as discarded, so it can no longer accept mutations. This does not delete cloud resources."],{code:'emfirge_discard_branch({ branch_id: "<branch_id>" })',language:"MCP tool call"}),
  ]},
  { slug:"changes",title:"Apply changes",group:"Work with branches",description:"Describe an infrastructure change as a small, typed mutation of your branch.",sections:[
    section("contract","The change contract",["Every mutation identifies the branch, operation, resource type, and resource ID. `fields` contains the properties to add or modify. Omit it for a delete."],{table:{headers:["Parameter","Type","Meaning"],rows:[["branch_id","string","ID of an open branch"],["op","add | modify | delete","Operation in the model"],["resource_type","string","Supported resource type"],["resource_id","string","Resource identifier"],["fields","object · optional","Schema fields for the mutation"]]}}),
    section("supported","Supported resources",["These resource types and operations can be changed on a branch. Collection coverage is broader than mutation coverage; a collected resource is not automatically editable. `GET /branches/capabilities` returns the authoritative, machine-readable contract, including field constraints. `GET /branches/field-catalog` lists every settable field and the AWS API member it stands for, with types, enums and patterns taken from AWS's botocore models. A value AWS would reject, such as an unknown instance type, is rejected with HTTP 422."],{table:{headers:["Resource type","Identity","Operations"],rows:[["ec2_instance","Instance ID","add · modify · delete"],["security_group","Security group ID","add · modify · delete (attachments are derived from EC2 `sg_ids`)"],["rds_instance","Database ID","add · modify · delete"],["s3_bucket","Bucket name","add · modify · delete"],["lambda_function","Function name","add · modify · delete"],["network_acl","Network ACL ID","add · modify · delete (modify replaces complete `entries` and/or `associated_subnet_ids`)"],["iam_role_policy","Role ARN","modify (replaces the complete `access_statements` list)"],["route_table","Route table ID (AWS assigns it for an add; omit to get a placeholder)","add (`vpc_id` of a VPC in the snapshot; copies the VPC local routes; optional `routes`, `associated_subnet_ids` and `tags`) · modify (replaces the complete `routes` list; new internet-gateway routes need attachment evidence)"],["iam_role","Role ARN","add · modify (trust policy) · delete"],["rds_snapshot","Snapshot ID","add (manual snapshot of an existing database) · delete"],["ebs_volume","Volume ID (AWS assigns it for an add; omit to get a placeholder)","add (`size_gb` required, `availability_zone`, `volume_type`, `tags`) · delete"],["ebs_snapshot","Snapshot ID","delete"],["iam_user","User name","add"],["nat_gateway","NAT gateway ID (AWS assigns it; omit to get a placeholder)","add (`subnet_id`, `connectivity_type` public or private, `allocation_id` for a public NAT)"]]}, note:"Anything Emfirge cannot model is never treated as safe: it degrades the verdict to warn or block. Impossible input, such as from_port greater than to_port, is rejected with a clear HTTP 422. A missing value AWS requires, such as a NAT gateway subnet or an EBS volume `availability_zone`, is accepted with an explicit `unspecified_values` warning instead of a guessed default. An EBS volume add uses the AWS default volume type (gp2) when `volume_type` is omitted. Adding a route table associates `associated_subnet_ids` with it, which moves each subnet off its old explicit table. Hand-back creates only the route table; routes and associations on a branch-created table are reported as a gap, because AWS assigns the table ID. Most resource types (EC2 instances, security groups, RDS instances, S3 buckets, Lambda functions, EBS volumes, NAT gateways and route tables) carry `tags`. A tag change replaces the complete user tag set: AWS allows 50 user tags, keys up to 128 characters and values up to 256, and `aws:` tags are kept and cannot be changed. Tag changes do not change findings or reachability. They warn when IAM policies have conditions, because tag-based (ABAC) access is not evaluated."}),
    section("modify","Modify a resource",["For example, disable the public-access flag on an existing database in the model. Use field names from Emfirge’s resource schema, not arbitrary AWS or Terraform property names."],{code:'emfirge_apply_change({\n  branch_id: "<branch_id>",\n  op: "modify",\n  resource_type: "rds_instance",\n  resource_id: "<database_id>",\n  fields: { publicly_accessible: false }\n})',language:"MCP tool call"}),
    section("add-delete","Add or delete a resource",["An add needs the fields required by the resource schema. A delete identifies an existing resource and removes it from the branch model. Review the resulting edges and findings before drawing conclusions.","A removed model relationship does not fully describe application-level dependencies. Dependency breakage beyond the graph needs separate validation."],{code:'emfirge_apply_change({\n  branch_id: "<branch_id>",\n  op: "delete",\n  resource_type: "ec2_instance",\n  resource_id: "<instance_id>"\n})',language:"MCP tool call"}),
  ]},
  {slug:"diffs",title:"Read diffs and verdicts",group:"Work with branches",description:"Understand what changed, why it matters, and what the model cannot establish.",sections:[
    section("diff","Read the infrastructure diff",["Request a diff at any point to compare the rebuilt branch with its original baseline."],{code:'emfirge_branch_diff({ branch_id: "<branch_id>" })',language:"MCP tool call",table:{headers:["Fields","What they describe"],rows:[["added_nodes / removed_nodes / modified_nodes","Resource changes"],["added_edges / removed_edges","Relationship changes"],["added_findings / removed_findings","Changes in native checks"],["newly_internet_reachable / no_longer_internet_reachable","Modeled reachability changes"],["score_before / score_after / score_delta","Score comparison; higher is safer"],["deletion_impacts / lost_dependencies / lost_connectivity","What a deletion breaks or disconnects"],["coverage_warnings / collection_warnings","What the model could not check; non-empty means the result is degraded"]]}, note:"Two-sided diff: `resources_added`, `resources_removed` and `resources_modified` with before and after values, plus `cost_before` and `cost_after`, including resource types that have no graph node."}),
    section("verdict","Interpret the verdict",["The combined verdict is native-rules-only by default; Checkov, Trivy, and cloudsplaining are disabled unless `EMFIRGE_RUN_SCANNERS=1`. When enabled, the verdict compares native checks with available scanner results and includes provisioned-cost notes. It is advisory; the backend does not stop an external AWS apply."],{table:{headers:["Result","When it happens","Example reason codes"],rows:[["block","The change introduces something critical, or Emfirge cannot see enough to judge it.","`introduced_critical_finding` · `introduced_critical_exposure` · `privilege_escalation` · `recently_used` · `usage_unknown` · `data_store_deleted_no_recovery_point` · `unseen_change` · `unmodeled_delete` · `unmodeled_risky_change`"],["warn","The change needs human review.","`introduced_finding` · `new_exposure` · `newly_internet_reachable` · `lost_dependency` · `lost_connectivity` · `deletion_impact` · `recovery_point_removed` · `capacity` · `unknown_plan_values`"],["pass","No lens raised a warning or block.","None"]]}}),
    section("reasons","Read the reasons",["Every verdict lists `reasons`. Each one has a `level` (block or warn), a stable `code`, and a human-readable `message`, so your agent can explain exactly why and decide what to change next. Only newly introduced problems count: an issue that already existed in the base does not block a branch.","Each reason also lists the `resources` it affects, and hand-back responses include a `next_step` your agent can follow."],{code:'{\n  "verdict": "block",\n  "reasons": [\n    { "level": "block", "code": "recently_used",\n      "message": "CloudWatch metrics show a deleted resource was used in the last 90 days",\n      "resources": ["orders-db"] }\n  ]\n}',language:"Verdict excerpt"}),
    section("coverage","Read coverage alongside the result",["Check `scanner_available`: false means optional scanner results were not available, not that the scanner found nothing. Read `cost_unknown_notes` even when a numeric cost delta is present.","The current combined-verdict response does not include a universal confidence field. Confidence tiers on graph findings and roadmap commitments should not be treated as fields guaranteed on every tool response."],{note:"A pass is a statement about the checks that ran. Missing scanner coverage, unknown prices, and unmodeled application dependencies still need review."}),
  ]},
  {slug:"plans",title:"Plans and hand-back",group:"Work with branches",description:"Bring the change you already have, whether a Terraform plan, a CloudFormation change set, AWS API calls, or AWS CLI commands, and get back a verdict bound to that exact change.",sections:[
    section("inputs","Four ways in, one change model",["Your agent does not have to translate its plan into Emfirge’s format. `emfirge_plan_verdict` accepts the change in the form it already exists, normalizes it into the same typed changes the branch uses, and returns the verdict.","Because every format becomes the same change model, an equivalent change gets the same verdict whichever way it arrives. This is enforced by tests for Terraform, CloudFormation, AWS API, and AWS CLI inputs."],{table:{headers:["format","What to pass as plan"],rows:[["terraform","The JSON from `terraform show -json <planfile>`"],["cloudformation","A change-set document"],["aws-api","A list of AWS API calls"],["aws-cli","A list of AWS CLI command strings"]]}}),
    section("example","Check a plan",["Emfirge never runs the plan. It applies the changes to the branch model, evaluates every lens, and reports which changes were applied, rejected, unmodeled, or had unknown fields."],{code:'emfirge_plan_verdict({\n  branch_id: "<branch_id>",\n  format: "aws-cli",\n  plan: [\n    "aws ec2 authorize-security-group-ingress --group-id <sg_id> --protocol tcp --port 22 --cidr 0.0.0.0/0"\n  ]\n})',language:"MCP tool call",note:"Unknown or unsupported values never pass silently. Changes Emfirge cannot model are listed and make the verdict stricter, and a change against a snapshot from a different region is rejected."}),
    section("handback","The hand-back",["When a branch or plan is approved, the hand-back gives you the exact change to apply. For a branch, `emfirge_branch_handback` returns the exact AWS API calls. For a plan, the hand-back is the exact input you submitted.","Each hand-back is bound by `input_sha256`, the base snapshot, the branch revision, and a `verdict_id`. Emfirge never applies it: you or your pipeline do."],{code:'emfirge_branch_handback({ branch_id: "<branch_id>", verify: true })',language:"MCP tool call"}),
    section("verify","Verify before you apply",["With `verify: true`, the backend recomputes the calls and checks that nothing changed since the verdict. A mismatch is reported with a reason instead of a stale approval."],{table:{headers:["Reason","Meaning"],rows:[["input_hash_mismatch","The calls are not the ones that were judged"],["base_snapshot_changed","The branch is now based on a different snapshot"],["branch_revision_changed","The branch changed after the verdict"],["verdict_changed","Re-evaluating produced a different verdict"]]},note:"Changes that cannot be expressed as AWS API calls come back as gaps (`unmappable_changes`), never as partial calls. Hand-back calls are tested by applying them to a simulated AWS (Moto) and re-reading the result."}),
  ]},
  {slug:"lenses",title:"Lenses and coverage",group:"Understand consequences",description:"Evaluate different consequences over the same infrastructure model, with explicit bounds on every conclusion.",sections:[
    section("security","Security and reachability",["The native engine evaluates findings and graph relationships, including internet-reachable resources and privilege-escalation signals. Attack paths and blast radius help explain effects beyond a single changed resource.","These are graph-based predictions. They are not live exploit execution or a complete evaluation of every IAM and network policy.","IAM privilege escalation uses the public pathfinding.cloud catalogue, and IAM access levels come from policy_sentry. If policy_sentry is unavailable, the verdict is marked degraded rather than silently passing.","Rules include trust policies open to anyone or to another account (EMFIRGE-IAM-009), internet-reachable resources with broad data access (EMFIRGE-IAM-008), and wildcard S3 grants. S3 buckets made public by a bucket policy, not only by ACLs, are detected using AWS's definition of public. Block Public Access settings, on the bucket and the account, are collected and respected. A public bucket policy on a bucket with BlockPublicPolicy on is rejected with HTTP 422."]),
    section("dependencies","Dependencies and delete safety",["When a branch deletes something, this lens asks what breaks. It reports lost dependencies (for example, a role an instance uses or a secret a function references), lost connectivity, and whether a deleted data store still has a recovery point.","A deleted database with no surviving snapshot blocks. A role or resource that was recently used blocks, and so does one whose usage could not be verified."],{note:"In-use evidence is opt-in. `emfirge_in_use_evidence` first shows exactly which CloudTrail and CloudWatch reads it would make and their cost; it reads nothing until you approve. Evidence can only make a verdict stricter."}),
    section("compliance","Compliance",["`emfirge_check_compliance` maps findings to CIS AWS Foundations 1.5 and SOC 2 controls and reports pass, fail, or not applicable per control. These are mapped checks, not an audit or certification."]),
    section("limits","Limits",["The limits lens checks deterministic AWS default quotas, such as security-group rules, Elastic IPs, and VPCs per region, and warns when a branch would breach one. It uses AWS default values, not your account’s approved quota increases, and does not forecast."]),
    section("scanners","Configuration checks",["The engine can serialize supported infrastructure and run Checkov as an additional configuration lens. A combined verdict compares before and after findings.","Inspect `scanner_available`. The scanner is optional, and incomplete serialization or an unavailable executable limits coverage."]),
    section("cost","Provisioned-cost estimates",["The current engine uses a small curated pricing table with a stated region and monthly-hour assumption. It reports known provisioned charges and identifies unknown prices or usage-based costs.","A live AWS Price List integration is a roadmap direction. Current values are estimates, not your AWS bill. RDS or other unsupported prices must not be invented."],{table:{headers:["Cost basis","Interpretation"],rows:[["provisioned-estimate","A supported resource with a known table price"],["usage-based-unknown","Requires actual usage information"],["price-unavailable","No supported price for the resource"]]}}),
    section("resilience","Availability and recovery",["Native rules and category scores include infrastructure configuration signals for availability and disaster recovery. These do not predict uptime, failover timing, or whether an application can serve a particular load."]),
    section("runtime","What needs a real run",["Application latency, throughput, runtime correctness, recovery time, and usage-based spend require execution or measured telemetry. Emfirge’s model does not produce those measurements."]),
  ]},
  {slug:"safety",title:"Safety and model limits",group:"Understand consequences",description:"Keep cloud access read-only and use branches to inspect modeled consequences through the documented lenses.",sections:[
    section("read-only","Read-only AWS access",["Emfirge collects infrastructure through an IAM role assumed with AWS STS. Review the CloudFormation template and its trust policy before connecting your account. The analysis and mutation tools do not apply changes to real AWS resources.","The setup flow creates an IAM role in your account. You approve that setup in AWS; subsequent proposed infrastructure changes stay in Emfirge’s model."]),
    section("advisory","Advisory by design",["A `block` verdict is an analysis result. Emfirge does not physically prevent an agent, user, or pipeline with separate AWS credentials from deploying. Any approval policy must be enforced by your own workflow."]),
    section("privacy","Privacy and data flow",["The local MCP server sends requests to the configured Emfirge backend. The backend collects and processes infrastructure information. Strict privacy mode tokenizes supported identifiers in covered tool responses before they reach the host model; it does not mean infrastructure stays only on your computer.","The checked-in branch handlers return backend JSON directly and do not apply the same tokenization wrapper used by scan and findings tools. Do not assume strict mode redacts every branch response."],{note:"Treat local token mappings and analysis output as sensitive infrastructure data. Review the client and backend behavior for the tools you use."}),
    section("confidence","Coverage and uncertainty",["Graph confidence and coverage depend on collected fields, modeled relationships, and the checks that ran. A model cannot establish application behavior or complete runtime reachability.","Prefer a precise limitation over an unsupported promise. Review scanner availability and unknown cost notes before taking action."]),
    section("revoke","Revoke AWS access",["Remove the CloudFormation stack that created the read-only role to revoke that role’s access. Removing the MCP client configuration alone does not remove the IAM role or stored scan data."]),
  ]},
  {slug:"configuration",title:"Configuration",group:"Integrate",description:"Configure the MCP transport, backend destination, and privacy settings for your agent.",sections:[
    section("stdio","MCP over stdio",["Emfirge is a local process launched by your MCP client. It communicates with the client over stdio and sends HTTP requests to the configured backend. Use the following server entry in a client that accepts JSON MCP configuration."],{code:MCP_CONFIG,language:"JSON"}),
    section("codex","Codex configuration",["The Emfirge installer writes this TOML block for Codex. Merge it with your existing configuration rather than replacing the whole file."],{code:CODEX_CONFIG,language:"~/.codex/config.toml"}),
    section("environment","Environment variables",[],{table:{headers:["Variable","Purpose"],rows:[["EMFIRGE_BASE_URL","Backend API URL; defaults to https://emfirge.cloud/api"],["EMFIRGE_PRIVACY","strict (default), balanced, or off"],["EMFIRGE_TRUSTED_ACCOUNT_ID","Overrides the trusted AWS account returned by the server for setup help"],["EMFIRGE_EXTERNAL_ID","Self-host ExternalId; required on the server and here (no default; scans refuse without it)"],["EMFIRGE_TEMPLATE_URL","CloudFormation template URL used by setup help"]]}}),
    section("self-host","Use your own backend",["Set `EMFIRGE_BASE_URL` in the MCP server environment to your backend’s API URL. Configure the role trust and ExternalId for that backend. A custom URL does not install or start an engine for you.","Keep the MCP tool set and backend routes compatible. If branch tools are absent, use a matching build of the client and engine."],{code:'"env": {\n  "EMFIRGE_BASE_URL": "https://your-emfirge-host.example/api",\n  "EMFIRGE_PRIVACY": "strict"\n}',language:"JSON server environment"}),
    section("verify","Inspect local setup",["The status command reports configured clients and privacy settings. Confirm that your agent can list Emfirge tools to verify the connection."],{code:"npx @emfirge/mcp status",language:"Terminal"}),
  ]},
  {slug:"troubleshooting",title:"Troubleshooting",group:"Resources",description:"Resolve common setup, scanning, and branch issues with a focused check.",sections:[
    section("tools","Emfirge tools do not appear",["Confirm Node.js 20 or later is available to your desktop client. Run `npx @emfirge/mcp status`, check the client’s MCP configuration, and restart the client.","If scan tools appear but branch tools do not, the installed MCP version may not match this source. Use matching MCP and engine builds."]),
    section("access","Access denied or 403",["Review the IAM role ARN, trusted account, and ExternalId. Ask your agent to call `emfirge_setup_help` to inspect the setup flow. Confirm that the role’s permissions allow the collection calls required by your backend."]),
    section("empty","The scan is empty",["Confirm the region with the account owner. Emfirge requires an explicit region because most resources are regional. Also check collection permissions. An empty result does not establish that the entire AWS account has no risks."]),
    section("not-found","Analysis or branch not found",["Use the exact ID returned by the tool and the same backend that created it. For an analysis, run a new scan if its stored record is no longer available. For branch-route errors, check client/backend version compatibility."]),
    section("mutation","A change is rejected",["Check that the branch is open, the resource type is supported, and the target resource exists for modify/delete. Unknown fields are rejected. See [Apply changes](/docs/changes) for the contract."]),
    section("limits","Timeouts and limits",["The scan client uses a streaming backend endpoint and waits up to 240 seconds. Check backend health and account size after a timeout. For a 429 response, follow the limit and reset information returned by your backend."]),
    section("scanner","Scanner unavailable",["A verdict may still return native results when Checkov is unavailable. Inspect `scanner_available`; verify the engine’s scanner installation and serialization support before treating scanner coverage as complete."]),
  ]},
  {slug:"glossary",title:"Glossary",group:"Resources",description:"A shared vocabulary for modeling cloud changes with Emfirge.",sections:[
    section("terms","Terms",[],{table:{headers:["Term","Meaning"],rows:[["Analysis","The result of collecting and evaluating an AWS account and region."],["Base","The saved infrastructure snapshot a branch starts from."],["Branch","A base snapshot plus an ordered list of hypothetical changes."],["Mutation","One add, modify, or delete operation in the model."],["Graph","Resources represented as nodes, connected by typed relationships."],["Lens","An evaluation of a particular aspect of the infrastructure model."],["Diff","The resources, relationships, findings, and reachability that changed."],["Verdict","An advisory pass, warn, or block from the current evaluation."],["Attack path","A modeled route from an entry point toward another resource."],["Blast radius","The modeled resources reachable after a compromise or change."],["MCP","Model Context Protocol: the interface used by an agent to call Emfirge tools."],["Needs a real run","A question the model cannot resolve without execution or measured data."]]}}),
  ]},
];

export type Tool = { name: string; description: string; params: string; group: string };
export const mcpTools: Tool[] = [
  {name:"emfirge_setup_help",description:"Return the CloudFormation setup link and read-only role instructions.",params:"No parameters.",group:"Setup and baseline"},
  {name:"emfirge_scan",description:"Collect an AWS account and region and return an analysis_id.",params:"role_arn: IAM role ARN · required; region: AWS region · required",group:"Setup and baseline"},
  {name:"emfirge_create_branch",description:"Create an isolated branch from a completed analysis.",params:"base_analysis_id: string · required; name: non-empty string · required",group:"Branch workflow"},
  {name:"emfirge_apply_change",description:"Append an add, modify, or delete mutation to the branch model.",params:"branch_id, resource_type, resource_id: string · required; op: add | modify | delete · required; fields: object · optional",group:"Branch workflow"},
  {name:"emfirge_branch_diff",description:"Compare a branch against its base: resources, relationships, findings, and reachability.",params:"branch_id: string · required",group:"Branch workflow"},
  {name:"emfirge_branch_verdict",description:"Evaluate the branch with native findings, optional scanner results, and cost notes.",params:"branch_id: string · required",group:"Branch workflow"},
  {name:"emfirge_rollback_branch",description:"Remove the most recent change from a branch in the current backend.",params:"branch_id: string · required",group:"Branch workflow"},
  {name:"emfirge_discard_branch",description:"Mark a branch as discarded without changing AWS.",params:"branch_id: string · required",group:"Branch workflow"},
  {name:"emfirge_list_branches",description:"List branches, optionally filtered by their base analysis.",params:"base_analysis_id: string · optional",group:"Branch workflow"},
  {name:"emfirge_compare_branches",description:"Compare modeled changes and outcomes for one or more branches.",params:"branch_ids: non-empty string array · required",group:"Branch workflow"},
  {name:"emfirge_get_branch",description:"Read a branch’s metadata, status, revision, and ordered change log without the base snapshot.",params:"branch_id: string · required",group:"Branch workflow"},
  {name:"emfirge_fork_branch",description:"Copy an open branch into a new independent branch with the same base and changes.",params:"branch_id: string · required; name: non-empty string · required",group:"Branch workflow"},
  {name:"emfirge_rollback_branch_to_count",description:"Keep only the first N changes of a branch, optionally rejecting stale state.",params:"branch_id: string · required; target_change_count: integer ≥ 0 · required; branch_revision: string · optional",group:"Branch workflow"},
  {name:"emfirge_plan_verdict",description:"Check a Terraform plan, CloudFormation change set, AWS API calls, or AWS CLI commands on a branch and return the verdict and hash-bound hand-back.",params:"branch_id: string · required; format: terraform | aws-api | aws-cli | cloudformation · required; plan: object or string array · required",group:"Plans and hand-back"},
  {name:"emfirge_branch_handback",description:"Return the exact AWS API calls for a branch, bound to its state by hash; optionally verify them.",params:"branch_id: string · required; verify: boolean · optional",group:"Plans and hand-back"},
  {name:"emfirge_in_use_evidence",description:"Estimate, then after approval read, CloudTrail and CloudWatch evidence for resources a branch deletes.",params:"branch_id: string · required; sources: cloudtrail_events | cloudwatch_metrics[] · optional; accept_estimate_id: string · optional; role_arn: string · optional",group:"Plans and hand-back"},
  {name:"emfirge_policy_checks",description:"Estimate, then after approval ask AWS IAM Access Analyzer whether changed S3 bucket policies and role trust policies are public.",params:"branch_id: string · required; approve: true · optional; accept_estimate_id: string · optional; role_arn: string · optional",group:"Plans and hand-back"},
  {name:"emfirge_login",description:"Sign in to Emfirge with GitHub or Google in your browser.",params:"No parameters.",group:"Account"},
  {name:"emfirge_logout",description:"Sign out of Emfirge on this device.",params:"No parameters.",group:"Account"},
  {name:"emfirge_link_project",description:"Link your browser sign-in to an existing API-key project.",params:"No parameters. Uses EMFIRGE_API_KEY from the MCP environment.",group:"Account"},
  {name:"emfirge_get_findings",description:"Retrieve findings from a scan, optionally filtered by severity.",params:"analysis_id: string · required; severity: Critical | Moderate | Low · optional",group:"Analysis tools"},
  {name:"emfirge_attack_paths",description:"Read modeled internet-to-internal paths, critical resources, orphans, and graph statistics.",params:"analysis_id: string · required",group:"Analysis tools"},
  {name:"emfirge_verify_fix",description:"Simulate one supported rule remediation against an analysis. Not every rule has a fix mutation.",params:"analysis_id, rule_id, resource_id: string · required",group:"Analysis tools"},
  {name:"emfirge_simulate_breach",description:"Evaluate a graph-based scenario without executing a real exploit.",params:"analysis_id: string · required; query: string, 3–500 characters · required",group:"Analysis tools"},
  {name:"emfirge_check_compliance",description:"Retrieve mapped CIS AWS Foundations 1.5 or SOC 2 control results. These checks do not constitute certification.",params:"analysis_id: string · required; framework: cis-aws-1.5 | soc2 · optional",group:"Analysis tools"},
];
