documents.splice(7, 0, {slug:"mcp",title:"MCP tool reference",group:"Integrate",description:"The typed interface your agent uses to fork infrastructure, explore changes, and inspect their consequences across the documented lenses.",sections:[
  section("using-tools", "Using the tools", ["Emfirge runs as an MCP server that your agent invokes over the local stdio connection. Each tool below is a registered operation; select its linked page for the full parameter and response details.", "Persist the analysis_id and branch_id returned by your own calls. Do not substitute IDs from screenshots or examples. A compatible engine is required for branch operations."]),
  ...mcpIndexGroups.map(([id, names]) => section(id, id, [], {table: {headers: ["Tool", "What it does"], rows: names.map(name => { const tool = mcpTools.find(candidate => candidate.name === name)!; return [`[${tool.name}](${mcpIndexRoutes[name]})`, tool.description]; })}})),
]});
const extra = (slug: string, title: string, group: string, description: string, sections: DocSection[]): Doc => ({slug,title,group,description,sections});
const legacyDocs: Doc[] = [
  extra("how-it-works","How the fork works","Get started","Build a read-only graph, fork it, model a change, and inspect consequences before deployment.",[section("harness","The harness between AI and cloud", ["An agent should not need direct access to a live account. Emfirge sits between the agent and cloud as a safe workspace: the agent proposes, Emfirge branches and measures the change, and your own pipeline decides what to apply." ]),section("workflow","The workflow", ["A scan builds a connected graph from a read-only role. Fork a completed analysis with `emfirge_create_branch`, add an operation with `emfirge_apply_change`, then inspect `emfirge_branch_diff` and `emfirge_branch_verdict`."],{code:'emfirge_create_branch({ base_analysis_id: "<analysis_id>", name: "restrict-public-access" })\nemfirge_apply_change({ branch_id: "<branch_id>", op: "modify", resource_type: "rds_instance", resource_id: "<database_id>", fields: { publicly_accessible: false } })\nemfirge_branch_verdict({ branch_id: "<branch_id>" })',language:"MCP tool calls"}),section("limits","Honest limits",["Branches are models, not deployments. Emfirge does not apply branch changes to AWS, and a result from any one lens does not prove application connectivity or every operational consequence. Re-scan when the live environment changes."])]),
  extra("graph","The infrastructure graph","Understand consequences","Explore attack paths, blast radius, chokepoints, and toxic combinations as queries over one graph.",[section("map","What the graph is",["Every scanned resource becomes a node and every relationship a directed edge. The public internet is a first-class node, so reachability is a literal path. The engine models supported service types; coverage is not universal and relationships such as `REACHES`, `uses_iam_role`, `can_access`, `REFERENCES_SECRET`, and subnet/VPC containment." ]),section("weights","Rank routes by effort",["Representative edge costs are used for path ranking, not as a universal range or a claim about all path lengths: metadata edges cost 0, normal reachability edges cost 1, selected relationship edges cost 2–3, and unknown relationships fall back to 3. Path ranking uses effort, not simply hop count: a five-hop route of trivial steps can outrank a two-hop route needing a shell and stolen credentials."],{table:{headers:["Representative cost","Meaning"],rows:[["0","Metadata or structural edge; no additional modeled effort"],["1","Normal reachability edge"],["2–3","Selected relationship edge requiring additional modeled effort"],["3","Unknown relationship fallback"]]}}),section("queries","One graph, many queries",["Attack paths are ranked by effort. Blast radius is an outbound-only search from a node. Chokepoints use betweenness centrality. Toxic combinations are nine curated multi-signal patterns, and orphaned resources are disconnected nodes often indicating cleanup or cost work."]),section("limits","Rules and limits",["The engine runs 51 verified check functions across the supported rule families and produces a 0–100 posture score, higher is safer, across security, availability, cost, and disaster recovery. Path-finding and blast radius are capped at 5 hops. The graph is a scan snapshot, not live AWS; coverage and exploit weights are bounded heuristics."])]),
  extra("security","Security as one lens","Safety & privacy","Emfirge is the harness between your AI agent and cloud: fork the infrastructure graph, model a proposed change, and inspect its consequences across the documented lenses before production. Security and reachability are one lens; read-only IAM access, scoped trust, temporary credentials, deterministic analysis, and revocation keep that lens bounded.",[section("role","The role",["Emfirge reads through a read-only IAM role you own and control, with no write permissions. Hosted users receive their own ExternalId from `emfirge_setup`; self-host deployments must set `EMFIRGE_EXTERNAL_ID` on the server and in the MCP environment. There is no default, and scans refuse to run without it. The role includes two read-only CloudWatch permissions (`GetMetricStatistics` and `GetMetricData`) for in-use evidence, and two IAM Access Analyzer permissions (`CheckNoPublicAccess` and `ValidatePolicy`) used only by opt-in policy checks. Roles made with the old shared ExternalId must be redeployed. Delete the CloudFormation stack to revoke access."]),section("setup","Set it up",["Ask your assistant for setup help, open the pre-filled CloudFormation URL, acknowledge the IAM-resources checkbox, create the stack (about 30 seconds), and copy `RoleArn` from Outputs before scanning."]),section("deterministic","Deterministic backend",["Scanning, rules, graph analysis, and verify-fix are pure computation: the same input produces the same output. Prose summaries are the only place a model is used, never inside the MCP path."]),section("errors","Retention and errors",["No backend-enforced scan-data retention period is documented. The CLI can request immediate deletion; presigned report URLs expire after one hour, which is separate from scan-data retention. A 403 usually means trust or ExternalId, a 404 means the analysis was not found, and a 429 means the default limit of 5 scans per account per local calendar day (override with `DAILY_SCAN_LIMIT`)."])]),
  extra("privacy","Privacy modes","Safety & privacy","Control which recognized AWS identifiers are tokenized before results reach your model.",[section("tokenization","How tokenization works",["The local MCP replaces recognized AWS identifiers with stable local tokens such as `SG_001` and `S3_001`. Later calls expand tokens locally, call the backend, and tokenize again. The mapping stays on your machine and is not sent to Emfirge or the model."],{code:'LLM sees:       "SG_001 reaches S3_001"\nlocal mapping:  SG_001 = <local security-group ID>\n                S3_001 = <local bucket ID>',language:"Example"}),section("modes","The three modes",["`strict` (default) tokenizes recognized AWS IDs, ARNs, account IDs, names, and IPs. `balanced` tokenizes common identifiers while retaining selected context. `off` leaves identifiers raw."]),section("change","Change the mode",["Use the CLI or set `EMFIRGE_PRIVACY` in client configuration."],{code:"npx @emfirge/mcp privacy\nnpx @emfirge/mcp privacy strict",language:"Terminal"}),section("boundary","Backend and report URLs",["The backend receives data required for analysis. Credentials in presigned report URLs are scrubbed. Derived graph labels may not be recognized identifiers, so tokenization is not a completeness guarantee."])]),
  extra("cli","CLI reference","CLI","Install, inspect, configure, and remove the Emfirge MCP client from the terminal.",[section("overview","The package and server",["With no subcommand the package runs as an MCP stdio server; with a subcommand it manages your install."]),section("commands","Commands",["`install` wires the server into detected client configs; `--privacy` avoids the prompt and defaults to strict. `status` prints wired clients, backend URL, and privacy mode. `privacy` shows or sets strict, balanced, or off. `tokens` lists local mappings at `~/.emfirge/tokens.json`, which never leaves your machine."],{code:"npx @emfirge/mcp --help\nnpx @emfirge/mcp install --privacy=strict\nnpx @emfirge/mcp status\nnpx @emfirge/mcp privacy strict\nnpx @emfirge/mcp tokens",language:"Terminal"}),section("purge","Purge scan data",["`purge --role-arn <role-arn>` deletes local token mappings and server-side scan data for that role. This permanently deletes records and has no undo."],{code:"npx @emfirge/mcp purge --role-arn arn:aws:iam::<account>:role/<name>",language:"Terminal",note:"Irreversible"})]),
  extra("self-host","Self-hosting","Self-hosting","Point the thin MCP client at your own backend with environment variables.",[section("backend","Point at your own backend",["The default backend is `https://emfirge.cloud/api`. Set `EMFIRGE_BASE_URL` in each client config. The thin MCP calls backend endpoints and tokenizes responses locally; dashboard URLs derive from the API base by stripping `/api`." ]),section("environment","Environment variables",[],{table:{headers:["Variable","Purpose and default"],rows:[["EMFIRGE_BASE_URL","Backend URL; default https://emfirge.cloud/api"],["EMFIRGE_PRIVACY","strict, balanced, or off"],["EMFIRGE_TRUSTED_ACCOUNT_ID","Trusted AWS account; default 000000000000"],["EMFIRGE_EXTERNAL_ID","Trust ExternalId; required on the server and here (no default; scans refuse without it)"],["EMFIRGE_TEMPLATE_URL","Template URL used by setup help"]]}}),section("license","Open source",["The MCP and a public backend mirror are open source under AGPL-3.0 for the root engine; the MCP is under Apache-2.0."])]),
  extra("faq","FAQ","Reference","Straight answers about what Emfirge is, what it can touch, what it stores, and what it does not claim.",[
    section("what","What is Emfirge, in one sentence?",["Emfirge is the harness between AI agents and your cloud: your agent gets a branch of your live AWS, tries its changes there, and gets back a diff and a pass / warn / block verdict before anything touches production."]),
    section("layers","What are the harness, the branch, and lenses?",["The harness is the product: where the agent works, what it may see, what it gets back, and what it cannot skip.","The branch is the engine: a snapshot of your AWS plus an ordered list of proposed changes, which you can fork, roll back, and compare. See [Create and compare branches](/docs/branches).","Lenses are what get measured on a branch: security, dependencies and delete safety, compliance, cost, and limits. See [Lenses and coverage](/docs/lenses)."]),
    section("why","Why not just read the Terraform plan?",["A plan tells you what actions will run. Emfirge tells you what those actions mean given everything else already in your account: what becomes reachable from the internet, which privilege-escalation paths open, what a deletion breaks, and what the model could not check. You can send it the plan you already have. See [Plans and hand-back](/docs/plans)."]),
    section("scanner","Is it a security scanner?",["No. A scanner looks at what is deployed now. Emfirge judges a proposed change before it exists. Security is its first lens, and it can also scan the current state, but the product is the branch your agent works on."]),
    section("changes-aws","Can Emfirge change or delete anything in my AWS account?",["No. Emfirge only has a read-only role, and every proposed change stays in its model. When you approve a change, Emfirge hands back the exact AWS API calls or the plan you sent; you or your pipeline apply them. See [Safety and model limits](/docs/safety)."]),
    section("access","What access does it need, and how do I revoke it?",["The setup creates an IAM role in your account with AWS’s managed `SecurityAudit` policy plus a few extra read permissions, and no write permissions. The role trusts only Emfirge’s AWS account and requires your own ExternalId, which prevents confused-deputy attacks. Credentials are temporary STS tokens that expire after an hour and are never stored. To revoke access instantly, delete the CloudFormation stack. See [Security model](/docs/security)."]),
    section("data","What do you store, and for how long?",["Scan results and infrastructure snapshots are kept for 90 days, then deleted automatically. Emfirge never reads the contents of your resources, such as S3 objects, database rows, or secret values. You can delete everything for your account at any time with `npx @emfirge/mcp purge --role-arn <your role ARN>`. The full details are in the repository’s PRIVACY.md."]),
    section("llm","What does my AI model see?",["In the default `strict` privacy mode, the MCP replaces recognized AWS identifiers, such as ARNs, account IDs, resource names, and IP addresses, with tokens on your machine before results reach the model. The mapping never leaves your computer. See [Privacy modes](/docs/privacy)."]),
    section("clients","Which AI tools does it work with?",["Any MCP client. The installer sets up Claude Code, Claude Desktop, Cursor, Codex, Kiro, Cline, and Continue automatically, and you can add it to any other MCP client by hand. See [Connect your agent](/connect)."]),
    section("clouds","Which clouds are supported?",["AWS only, by design. Emfirge goes deep on one cloud before adding others. A change to a non-AWS provider in a plan is flagged with a warning, never silently passed."]),
    section("what-changes","What changes can a branch model today?",["EC2 instances, security groups, RDS instances, S3 buckets, Lambda functions, network ACLs, and IAM roles (including trust policies) support add, modify, and delete. IAM users and NAT gateways support add, RDS snapshots and EBS volumes support add and delete, route tables support add and modify, IAM role policies support modify, and EBS snapshots support delete. More types are on the way. The full table is in [Apply changes](/docs/changes)."]),
    section("pass","Does a pass mean the change is safe?",["No. A pass means none of the lenses that ran found a problem. It is evidence, not a guarantee: a branch is a model, and some things, like runtime behavior or application-level dependencies, need a real run. If any check could not run, the verdict says so in `coverage_warnings` instead of hiding it."]),
    section("unmodeled","What happens with a change Emfirge cannot model?",["It is never treated as safe. Unmodeled deletes and risky calls block, other unmodeled changes warn, and unknown plan values are listed so your agent knows what was not checked."]),
    section("trust","How do you know the engine is right?",["Every behavior is pinned by numbered laws: property-based tests that must always hold, such as “the same inputs always give the same verdict” and “a Terraform change and the equivalent AWS API call get the same verdict.” Locked incident scenarios and 92 privilege-escalation paths from pathfinding.cloud run on every CI build."]),
    section("limits","How long does a scan take, and are there limits?",["Most scans take 30–60 seconds; larger accounts take longer. The hosted service allows five scans per AWS account per day, reset at midnight UTC. Findings, attack paths, branches, and verdicts on an existing scan do not use another scan."]),
    section("open-source","Is it open source? Can I self-host?",["Yes. The engine is AGPL-3.0 and the MCP package is Apache-2.0. You can run your own backend and point the MCP at it with `EMFIRGE_BASE_URL`. See [Self-hosting](/docs/self-host)."]),
    section("who","Who builds Emfirge?",["Emfirge is designed and built by Ansh Sonkar. For questions, partnerships, or to try it with your team, email ansh@emfirge.cloud."]),
  ]),
];
